script:
# Defaults for new leads: C-stage starts at C0, engagement starts at Active.
if doc.is_new():
    if not doc.status:
        if frappe.db.exists("CRM Lead Status", "C0"):
            doc.status = "C0"
        else:
            open_statuses = frappe.db.get_all("CRM Lead Status", filters={"type": "Open"}, pluck="name")
            if open_statuses:
                doc.status = open_statuses[0]
            else:
                frappe.throw(_("No open lead statuses configured. Run bench migrate or create a CRM Lead Status with type 'Open'."))
    if not doc.lead_status:
        doc.lead_status = "Active"

# Defensive: any record arriving without lead_status defaults to Active.
if not doc.lead_status:
    doc.lead_status = "Active"

ALLOWED_STATUS_TRANSITIONS = {
    "C0":   {"C1", "C2", "C6", "C7"},
    "C1":   {"C2", "C6", "C7"},
    "C2":   {"C2-Q", "C3", "C6", "C7"},
    "C2-Q": {"C3", "C6", "C7"},
    "C3":   {"C4", "C5", "C8", "C6"},
    "C4":   {"C5", "C8"},
    "C5":   {"C8"},
    "C6":   set(),
    "C7":   {"C6", "C8"},
    "C8":   set(),
}

ALLOWED_LEAD_STATUS_TRANSITIONS = {
    "Active":            {"Cold-Unresponsive", "Archived"},
    "Cold-Unresponsive": {"Reactivated", "Archived", "Active"},
    "Reactivated":       {"Active", "Cold-Unresponsive", "Archived"},
    "Archived":          {"Active"},
}

if not doc.is_new():
    old_doc = doc.get_doc_before_save()
    old_status = old_doc.status if old_doc else None
    old_lead_status = old_doc.lead_status if old_doc else None
    new_status = doc.status

    # Auto-flip Reactivated -> Active when the C-stage advances (PRD §7).
    if old_status and old_status != new_status and doc.lead_status == "Reactivated":
        doc.lead_status = "Active"

    # Terminal C-stages (C6, C8) force engagement to Active.
    if new_status in ("C6", "C8") and doc.lead_status != "Active":
        doc.lead_status = "Active"

    new_lead_status = doc.lead_status

    status_changed = bool(old_status) and old_status != new_status
    lead_status_changed = bool(old_lead_status) and old_lead_status != new_lead_status

    if status_changed or lead_status_changed:
        user_roles = {r["role"] for r in frappe.db.get_all("Has Role", filters={"parent": frappe.session.user, "parenttype": "User"}, fields=["role"])}
        is_privileged = "Administrator" in user_roles or "Sales Manager" in user_roles
        if not is_privileged:
            if "B2F Team" in user_roles:
                if status_changed and (old_status != "C7" or new_status not in ("C6", "C8")):
                    frappe.throw(_("B2F Team can only update C7 leads to C6 or C8"))
            elif "Jr. Sales Executive" in user_roles:
                if status_changed and new_status not in ("C1", "C2", "C6"):
                    frappe.throw(_("Spotters can only move leads to C1, C2, or C6"))
            elif "Calling Team" in user_roles:
                old_state_ok = old_status == "C0" or old_lead_status in ("Cold-Unresponsive", "Reactivated")
                if not old_state_ok:
                    frappe.throw(_("Calling Team can only manage leads at C0 or with engagement Cold-Unresponsive/Reactivated"))
                if status_changed and new_status not in ("C0", "C1", "C2", "C6", "C7"):
                    frappe.throw(_("Calling Team can only move C-stage to C0, C1, C2, C6, or C7"))
                if lead_status_changed and new_lead_status not in ("Active", "Cold-Unresponsive", "Reactivated", "Archived"):
                    frappe.throw(_("Calling Team can only set engagement to Active, Cold-Unresponsive, Reactivated, or Archived"))
            elif "Estimation Team" in user_roles:
                if status_changed and (old_status != "C2-Q" or new_status not in ("C3", "C6", "C7")):
                    frappe.throw(_("Estimation Team can only move C2-Q leads to C3, C6, or C7"))
            else:
                if doc.lead_owner != frappe.session.user:
                    frappe.throw(_("You can only change the status of leads you own"))

            # Task completion guards (bypassed by Sales Manager / Administrator)
            if status_changed and old_status == "C2-Q" and new_status not in ("C6", "C7"):
                latest_quote_status = frappe.db.get_value(
                    "CRM Quote Request",
                    {"lead": doc.name},
                    "status",
                    order_by="creation desc",
                )
                if latest_quote_status != "Accepted":
                    frappe.throw(
                        _("Cannot advance from C2-Q until the Lead Owner has accepted the Quote Request. Open the Quote Request and set its status to 'Accepted'."),
                        title=_("Quote Approval Required"),
                    )

            if status_changed and old_status == "C7":
                pending = frappe.db.get_value(
                    "CRM Task",
                    {
                        "reference_doctype": "CRM Lead",
                        "reference_docname": doc.name,
                        "task_type": "handle_fabricator_lead",
                        "status": ["not in", ["Done", "Canceled"]],
                    },
                    "name",
                )
                if pending:
                    frappe.throw(
                        _("Complete the 'Handle Fabricator Lead' task before updating the lead status."),
                        title=_("Task Incomplete"),
                    )

        if status_changed and old_status in ALLOWED_STATUS_TRANSITIONS:
            if new_status not in ALLOWED_STATUS_TRANSITIONS.get(old_status, set()):
                frappe.throw(_(f"Cannot move C-stage from {old_status} to {new_status}"))

        if lead_status_changed and old_lead_status in ALLOWED_LEAD_STATUS_TRANSITIONS:
            if new_lead_status not in ALLOWED_LEAD_STATUS_TRANSITIONS.get(old_lead_status, set()):
                frappe.throw(_(f"Cannot move engagement from {old_lead_status} to {new_lead_status}"))

old_doc = doc.get_doc_before_save()
old_status = old_doc.status if old_doc else None

if old_status != doc.status and doc.status == "Quote Received":
    updates = {}
    if doc.quote_value:
        updates["custom_tentative_value"] = doc.quote_value
        updates["custom_final_price"] = doc.quote_value
    if doc.quote_margin:
        updates["custom_final_margin"] = doc.quote_margin
    if doc.quote_file:
        updates["custom_final_quote"] = doc.quote_file
    if updates:
        frappe.db.set_value("CRM Lead", doc.lead, updates)

    open_upload_task = frappe.db.get_value("CRM Task", {
        "reference_doctype": "CRM Lead",
        "reference_docname": doc.lead,
        "task_type": "upload_quote",
        "status": ["in", ["Todo", "In Progress"]],
    }, "name")
    if open_upload_task:
        frappe.db.set_value("CRM Task", open_upload_task, "status", "Done")

    lead_owner = frappe.db.get_value("CRM Lead", doc.lead, "lead_owner")
    if not frappe.db.exists("CRM Task", {
        "reference_doctype": "CRM Lead",
        "reference_docname": doc.lead,
        "task_type": "review_quote",
        "status": ["in", ["Todo", "In Progress"]],
    }):
        review_task = {
            "doctype": "CRM Task",
            "task_type": "review_quote",
            "title": f"Review & Share Quote — {doc.lead_name or doc.lead}",
            "status": "Todo",
            "priority": "High",
            "reference_doctype": "CRM Lead",
            "reference_docname": doc.lead,
            "description": f"Quote received for {doc.lead_name or doc.lead} (Value: {doc.quote_value}). Review the quotation and share it with the customer.",
        }
        # Orphan-by-design: if the lead has no owner yet (common on C0->C2-Q before reassignment), insert the task unassigned -- Sales Manager / System Manager triage it via the all-tasks view (see admin-ui-setup-guide.md Script 5 commentary).
        if lead_owner:
            review_task["assigned_to"] = lead_owner
        frappe.get_doc(review_task).insert(ignore_permissions=True)

if old_status != doc.status and doc.status == "Revision Requested":
    # Lead Owner has reviewed and asked for revision — close their stale
    # review_quote task. Script 14 spawns a fresh upload_quote task for
    # Estimation in the same save.
    open_review_task = frappe.db.get_value("CRM Task", {
        "reference_doctype": "CRM Lead",
        "reference_docname": doc.lead,
        "task_type": "review_quote",
        "status": ["in", ["Todo", "In Progress"]],
    }, "name")
    if open_review_task:
        frappe.db.set_value("CRM Task", open_review_task, "status", "Done")

if old_status != doc.status and doc.status == "Accepted":
    # Mark Review & Share task Done
    review_task = frappe.db.get_value("CRM Task", {
        "reference_doctype": "CRM Lead",
        "reference_docname": doc.lead,
        "task_type": "review_quote",
        "status": ["in", ["Todo", "In Progress"]],
    }, "name")
    if review_task:
        frappe.db.set_value("CRM Task", review_task, "status", "Done")

    # Advance lead C2-Q -> C3 via db.set_value (bypasses Stage Transition guard;
    # safe because the Accept action is server-verified by the QR state change).
    current_lead_status = frappe.db.get_value("CRM Lead", doc.lead, "status")
    if current_lead_status == "C2-Q":
        frappe.db.set_value("CRM Lead", doc.lead, "status", "C3")

old_doc = doc.get_doc_before_save()
old_status = old_doc.status if old_doc else None
new_status = doc.status

if old_doc is not None and old_status != new_status and new_status in ("Quote Received", "Revision Requested", "Accepted"):
    if new_status == "Quote Received":
        parts = []
        if doc.quote_value:
            parts.append(f"Value: {doc.quote_value}")
        if doc.quote_margin:
            parts.append(f"Margin: {doc.quote_margin}%")
        meta = ", ".join(parts) if parts else "Quote uploaded."
        file_link = ""
        if doc.quote_file:
            file_link = f" — <a href='{doc.quote_file}' target='_blank' rel='noopener'>View File</a>"
        content = f"[AUTOMATION] Quote uploaded — {meta}{file_link}"
    elif new_status == "Revision Requested":
        reason = doc.revision_notes or "(no reason provided)"
        content = f"[AUTOMATION] Quote revision requested: {reason}"
    else:
        content = "[AUTOMATION] Quote accepted — lead advanced to C3."

    try:
        frappe.get_doc({
            "doctype": "Comment",
            "comment_type": "Comment",
            "reference_doctype": "CRM Lead",
            "reference_name": doc.lead,
            "content": content,
        }).insert(ignore_permissions=True)
    except Exception:
        # Comment is audit-only; never block the save.
        pass

    # Mirror the uploaded quote file onto the parent Lead so every round's PDF
    # surfaces in the Lead's Attachments side panel. Uses create_attachment_copy
    # to clone the File row reusing the same file_url (no disk duplication).
    # Idempotent: skipped when a Lead-attached File with this file_url already
    # exists, so a stray re-save with no file change doesn't double-mirror.
    if new_status == "Quote Received" and doc.quote_file and doc.lead:
        qr_file = frappe.db.get_value(
            "File",
            {
                "attached_to_doctype": "CRM Quote Request",
                "attached_to_name": doc.name,
                "file_url": doc.quote_file,
            },
            "name",
        )
        already_mirrored = frappe.db.exists(
            "File",
            {
                "attached_to_doctype": "CRM Lead",
                "attached_to_name": doc.lead,
                "file_url": doc.quote_file,
            },
        )
        if qr_file and not already_mirrored:
            try:
                frappe.get_doc("File", qr_file).create_attachment_copy(
                    attached_to_doctype="CRM Lead",
                    attached_to_name=doc.lead,
                    ignore_permissions=True,
                )
            except Exception:
                # Mirror is best-effort; the file is still visible on the QR.
                frappe.log_error(
                    message=f"Failed to mirror {doc.quote_file} from QR {doc.name} to lead {doc.lead}",
                    title="Quote file mirror to Lead failed",
                )

    if new_status == "Revision Requested":
        if not frappe.db.exists("CRM Task", {
            "reference_doctype": "CRM Lead",
            "reference_docname": doc.lead,
            "task_type": "upload_quote",
            "status": ["in", ["Todo", "In Progress"]],
        }):
            reason = doc.revision_notes or "(no reason provided)"
            frappe.get_doc({
                "doctype": "CRM Task",
                "task_type": "upload_quote",
                "title": f"Upload Revised Quote — {doc.lead_name or doc.lead}",
                "status": "Todo",
                "priority": "High",
                "reference_doctype": "CRM Lead",
                "reference_docname": doc.lead,
                "description": f"Revision requested for lead {doc.lead_name or doc.lead}: {reason}. Re-upload via the Upload Quote button on this task.",
            }).insert(ignore_permissions=True)

old_doc = doc.get_doc_before_save()
old_assignee = old_doc.assigned_to if old_doc else None
new_assignee = doc.assigned_to

if doc.task_type == "upload_quote" and not old_assignee and new_assignee and doc.reference_doctype == "CRM Lead":
    try:
        frappe.get_doc({
            "doctype": "Comment",
            "comment_type": "Comment",
            "reference_doctype": "CRM Lead",
            "reference_name": doc.reference_docname,
            "content": f"[AUTOMATION] Upload Quote task claimed by {new_assignee}.",
        }).insert(ignore_permissions=True)
    except Exception:
        pass

user_roles = {r["role"] for r in frappe.db.get_all("Has Role", filters={"parent": user, "parenttype": "User"}, fields=["role"])}

if "System Manager" in user_roles or "Sales Manager" in user_roles:
    conditions = ""
elif "B2F Team" in user_roles and "Estimation Team" in user_roles:
    conditions = "`tabCRM Lead`.status IN ('C7', 'C2-Q')"
elif "B2F Team" in user_roles:
    conditions = "`tabCRM Lead`.status = 'C7'"
elif "Estimation Team" in user_roles:
    conditions = "`tabCRM Lead`.status = 'C2-Q'"
else:
    conditions = ""

user_roles = {r["role"] for r in frappe.db.get_all("Has Role", filters={"parent": user, "parenttype": "User"}, fields=["role"])}

if "Sales Manager" in user_roles:
    conditions = ""
else:
    escaped_user = frappe.db.escape(user)
    base = f"""(
        `tabCRM Task`.assigned_to = {escaped_user}
        OR (
            `tabCRM Task`.reference_doctype = 'CRM Lead'
            AND EXISTS (
                SELECT 1 FROM `tabCRM Lead`
                WHERE `tabCRM Lead`.name = `tabCRM Task`.reference_docname
                AND `tabCRM Lead`.lead_owner = {escaped_user}
            )
        )
    )"""

    pool_clause = None
    if "Estimation Team" in user_roles:
        pool_clause = "(`tabCRM Task`.assigned_to IS NULL OR `tabCRM Task`.assigned_to = '') AND `tabCRM Task`.task_type = 'upload_quote'"
    elif "Calling Team" in user_roles:
        pool_clause = "(`tabCRM Task`.assigned_to IS NULL OR `tabCRM Task`.assigned_to = '') AND `tabCRM Task`.task_type = 'call_lead'"
    elif "B2F Team" in user_roles:
        pool_clause = "(`tabCRM Task`.assigned_to IS NULL OR `tabCRM Task`.assigned_to = '') AND `tabCRM Task`.task_type = 'handle_fabricator_lead'"

    if pool_clause:
        conditions = f"({base} OR ({pool_clause}))"
    else:
        conditions = base

POOL_TASK_ROLES = {
    "call_lead": "Calling Team",
    "upload_quote": "Estimation Team",
    "handle_fabricator_lead": "B2F Team",
}

# Immutability gate: task_type must not change after the task is created.
# Pool semantics + audit rely on the type being fixed — a call_lead row silently
# becoming an upload_quote row breaks every downstream filter and report.
# Privileged roles + ignore_permissions can still fix mistakes.
old_doc = doc.get_doc_before_save()
if old_doc and old_doc.task_type and doc.task_type != old_doc.task_type:
    actor = frappe.session.user
    actor_roles = {r["role"] for r in frappe.db.get_all("Has Role", filters={"parent": actor, "parenttype": "User"}, fields=["role"])}
    is_priv = actor == "Administrator" or bool(actor_roles & {"System Manager", "Sales Manager"})
    if not is_priv and not doc.flags.get("ignore_permissions"):
        frappe.throw(
            _(f"task_type cannot be changed after the task is created (was {old_doc.task_type!r}, attempted {doc.task_type!r})."),
            frappe.PermissionError,
            title=_("Task Type Locked"),
        )

user = frappe.session.user
if user == "Administrator" or doc.flags.get("ignore_permissions"):
    pass
else:
    user_roles = {r["role"] for r in frappe.db.get_all("Has Role", filters={"parent": user, "parenttype": "User"}, fields=["role"])}
    if not ("System Manager" in user_roles or "Sales Manager" in user_roles):
        task_type = doc.task_type or ""
        if task_type in POOL_TASK_ROLES:
            required_role = POOL_TASK_ROLES[task_type]
            if required_role not in user_roles and doc.assigned_to != user:
                frappe.throw(
                    _(f"Only {required_role} members can update this task."),
                    frappe.PermissionError,
                    title=_("Not Permitted"),
                )
        elif doc.assigned_to and doc.assigned_to != user:
            lead_owner = None
            if doc.reference_doctype == "CRM Lead" and doc.reference_docname:
                lead_owner = frappe.db.get_value("CRM Lead", doc.reference_docname, "lead_owner")
            if lead_owner != user:
                frappe.throw(
                    _("You can only update tasks assigned to you or for leads you own."),
                    frappe.PermissionError,
                    title=_("Not Permitted"),
                )

POOL_TASK_ROLES = {
    "call_lead": "Calling Team",
    "upload_quote": "Estimation Team",
    "handle_fabricator_lead": "B2F Team",
}

user = frappe.session.user
if user == "Administrator" or doc.flags.get("ignore_permissions"):
    pass
else:
    user_roles = {r["role"] for r in frappe.db.get_all("Has Role", filters={"parent": user, "parenttype": "User"}, fields=["role"])}
    if not ("System Manager" in user_roles or "Sales Manager" in user_roles):
        if (doc.task_type or "") in POOL_TASK_ROLES:
            frappe.throw(
                _("Pool tasks cannot be deleted. Mark the task as Done or Canceled instead."),
                frappe.PermissionError,
                title=_("Not Permitted"),
            )
        elif doc.assigned_to and doc.assigned_to != user:
            lead_owner = None
            if doc.reference_doctype == "CRM Lead" and doc.reference_docname:
                lead_owner = frappe.db.get_value("CRM Lead", doc.reference_docname, "lead_owner")
            if lead_owner != user:
                frappe.throw(
                    _("You can only delete tasks assigned to you or for leads you own."),
                    frappe.PermissionError,
                    title=_("Not Permitted"),
                )

user_roles = {r["role"] for r in frappe.db.get_all("Has Role", filters={"parent": user, "parenttype": "User"}, fields=["role"])}

if "Sales Manager" in user_roles or "Estimation Team" in user_roles:
    conditions = ""
else:
    escaped_user = frappe.db.escape(user)
    conditions = f"""(
        EXISTS (
            SELECT 1 FROM `tabCRM Lead`
            WHERE `tabCRM Lead`.name = `tabCRM Quote Request`.lead
            AND `tabCRM Lead`.lead_owner = {escaped_user}
        )
        OR EXISTS (
            SELECT 1 FROM `tabCRM Task`
            WHERE `tabCRM Task`.reference_doctype = 'CRM Lead'
            AND `tabCRM Task`.reference_docname = `tabCRM Quote Request`.lead
            AND `tabCRM Task`.assigned_to = {escaped_user}
        )
    )"""

old_doc = doc.get_doc_before_save()
old_disposition = old_doc.disposition if old_doc else None
new_disposition = doc.disposition

if new_disposition and new_disposition != old_disposition:
    disp = frappe.db.get_value(
        "CRM Call Disposition",
        new_disposition,
        ["next_status", "next_lead_status", "default_lost_reason"],
        as_dict=True,
    ) or {}
    next_status = disp.get("next_status")
    next_lead_status = disp.get("next_lead_status")
    default_reason = disp.get("default_lost_reason")

    if next_status or next_lead_status:
        lead_name = None
        if doc.reference_doctype == "CRM Lead" and doc.reference_docname:
            lead_name = doc.reference_docname
        else:
            for row in (doc.links or []):
                if row.link_doctype == "CRM Lead" and row.link_name:
                    lead_name = row.link_name
                    break
        if lead_name:
            current = frappe.db.get_value(
                "CRM Lead", lead_name, ["status", "lead_status"], as_dict=True
            ) or {}
            gate_ok = current.get("status") == "C0" or current.get("lead_status") in ("Cold-Unresponsive", "Reactivated")
            if gate_ok:
                try:
                    lead = frappe.get_doc("CRM Lead", lead_name)
                    changed = False
                    if next_status and next_status != lead.status:
                        lead.status = next_status
                        changed = True
                    if next_lead_status and next_lead_status != lead.lead_status:
                        lead.lead_status = next_lead_status
                        changed = True
                    if default_reason and not lead.lost_reason:
                        lead.lost_reason = default_reason
                    if changed:
                        lead.save(ignore_permissions=True)
                except Exception:
                    # Disposition still recorded; lead validation (e.g. lost_reason mandatory on C6,
                    # or transition not allowed) blocked the move.
                    frappe.log_error(
                        message=f"Lead {lead_name} could not auto-move for disposition {new_disposition!r}: current_status={current.get('status')}, current_lead_status={current.get('lead_status')}, next_status={next_status}, next_lead_status={next_lead_status}. Lead validation rejected the change. Agent must finalise the stage manually.",
                        title="Disposition stage move skipped — lead validation failed",
                    )

    if new_disposition == "Requested Callback":
        lead_name = None
        if doc.reference_doctype == "CRM Lead" and doc.reference_docname:
            lead_name = doc.reference_docname
        else:
            for row in (doc.links or []):
                if row.link_doctype == "CRM Lead" and row.link_name:
                    lead_name = row.link_name
                    break
        if lead_name:
            lead_state = frappe.db.get_value(
                "CRM Lead", lead_name, ["status", "lead_status"], as_dict=True
            ) or {}
            if lead_state.get("status") == "C0" or lead_state.get("lead_status") in ("Cold-Unresponsive", "Reactivated"):
                frappe.enqueue(
                    "crm.api.call_log.cancel_retry_log",
                    queue="short",
                    lead_name=lead_name,
                    permanent=False,
                )

old_doc = doc.get_doc_before_save()
old_status = old_doc.status if old_doc else None

if doc.status == "No Answer" and old_status != "No Answer":
    lead_name = None
    if doc.reference_doctype == "CRM Lead" and doc.reference_docname:
        lead_name = doc.reference_docname
    else:
        for row in (doc.links or []):
            if row.link_doctype == "CRM Lead" and row.link_name:
                lead_name = row.link_name
                break
    if lead_name:
        lead_state = frappe.db.get_value(
            "CRM Lead", lead_name, ["status", "lead_status"], as_dict=True
        ) or {}
        if lead_state.get("status") == "C0" or lead_state.get("lead_status") in ("Cold-Unresponsive", "Reactivated"):
            frappe.enqueue(
                "crm.api.call_log.register_no_answer",
                queue="short",
                lead_name=lead_name,
            )

old_doc = doc.get_doc_before_save()
old_disposition = old_doc.disposition if old_doc else None
new_disposition = doc.disposition

# Only validate when the disposition value is actually changing.
# (No-op saves and inserts without a disposition are skipped.)
if new_disposition and new_disposition != old_disposition:
    user = frappe.session.user
    user_roles = {r["role"] for r in frappe.db.get_all("Has Role", filters={"parent": user, "parenttype": "User"}, fields=["role"])}
    is_privileged = bool(user_roles & {"Sales Manager", "System Manager", "Administrator"})

    if not is_privileged and user not in (doc.caller, doc.receiver):
        frappe.throw(
            _("You can only set the disposition on calls you handled."),
            exc=frappe.PermissionError,
            title=_("Not Allowed"),
        )

    # Multiple no-answers escalate to Cold via the retry engine (PRD §5.2);
    # the agent has no discretion to relabel a No Answer call.
    if doc.status == "No Answer" and new_disposition != "No Answer / Not Reachable":
        frappe.throw(
            _("A No Answer call can only be tagged 'No Answer / Not Reachable'."),
            title=_("Disposition Not Allowed"),
        )

    # Per-disposition required fields. Schema lives on CRM Call Disposition
    # (requires_callback_datetime / _routing_reason / _lost_reason). Privileged
    # users are still subject to these — they describe data integrity, not policy.
    disp = frappe.db.get_value(
        "CRM Call Disposition",
        new_disposition,
        ["requires_callback_datetime", "requires_routing_reason", "requires_lost_reason"],
        as_dict=True,
    ) or {}

    if disp.get("requires_callback_datetime") and not doc.get("scheduled_callback_at"):
        frappe.throw(
            _(f"Disposition '{new_disposition}' requires a Scheduled Callback At datetime on this call log."),
            title=_("Callback Datetime Required"),
        )

    lead_name = None
    if doc.reference_doctype == "CRM Lead" and doc.reference_docname:
        lead_name = doc.reference_docname
    else:
        for row in (doc.links or []):
            if row.link_doctype == "CRM Lead" and row.link_name:
                lead_name = row.link_name
                break

    if lead_name and disp.get("requires_routing_reason"):
        if not frappe.db.get_value("CRM Lead", lead_name, "custom_fabricator_routing_reason"):
            frappe.throw(
                _(f"Disposition '{new_disposition}' requires Fabricator Routing Reason on the linked lead. Set it on the lead before saving the call."),
                title=_("Routing Reason Required"),
            )

    if lead_name and disp.get("requires_lost_reason"):
        lr = frappe.db.get_value("CRM Lead", lead_name, ["lost_reason", "lost_notes"], as_dict=True) or {}
        if not lr.get("lost_reason"):
            frappe.throw(
                _(f"Disposition '{new_disposition}' requires a Lost Reason on the linked lead. Set it on the lead before saving the call."),
                title=_("Lost Reason Required"),
            )
        if lr.get("lost_reason") == "Other" and not lr.get("lost_notes"):
            frappe.throw(
                _("Lost Reason 'Other' additionally requires Lost Notes on the linked lead."),
                title=_("Lost Notes Required"),
            )
